package org.jlinalg.cli;

import java.nio.file.*;
import java.util.*;
import org.jlinalg.singlecell.CellPhoneDbStatistics;
import static org.jlinalg.cli.Monocle3WorkflowRequest.*;

/** Actual packaged native controls, including all supplied permutation matrices. */
public final class CellPhoneDbStatisticsMatrix {
    private CellPhoneDbStatisticsMatrix() { }
    private static double number(Object value)throws Exception{return finite(value,-Double.MAX_VALUE,Double.MAX_VALUE);}
    private static List<String> texts(Object raw)throws Exception{var result=new ArrayList<String>();for(Object value:list(raw))result.add(text(value));return List.copyOf(result);}
    private static List<Long> ids(Object raw)throws Exception{var result=new ArrayList<Long>();for(Object value:list(raw))result.add(integer(value,Long.MIN_VALUE,Long.MAX_VALUE));return List.copyOf(result);}
    private static double[][] matrix(Object raw)throws Exception{var rows=list(raw);double[][] result=new double[rows.size()][];for(int i=0;i<rows.size();i++){var row=list(rows.get(i));result[i]=new double[row.size()];for(int j=0;j<row.size();j++)result[i][j]=number(row.get(j));}return result;}
    private static Object values(double[][] matrix){var result=new ArrayList<Object>();for(double[] row:matrix){var next=new ArrayList<Object>();for(double value:row)next.add(Double.isFinite(value)?value:Double.isNaN(value)?"NaN":value>0?"+Inf":"-Inf");result.add(next);}return result;}
    private static Object values(int[][] matrix){if(matrix==null)return null;var result=new ArrayList<Object>();for(int[] row:matrix){var next=new ArrayList<Integer>();for(int value:row)next.add(value);result.add(next);}return result;}
    private static Object significant(CellPhoneDbStatistics.Significant result){return result==null?null:Map.of("means",values(result.means()),"ranks",result.ranks());}
    public static void main(String[] args)throws Exception {
        require(args.length==2,"Need complete cases and NEW output directory");Path input=Path.of(args[0]),out=Path.of(args[1]);byte[] original=NextflowFiles.bytes(input,67108864);var root=object(NextflowParameters.parse(NextflowFiles.utf8(original),67108864,4000000));require(!Files.exists(out),"Existing native controls protected");Files.createDirectory(out);var results=new ArrayList<Object>();var warnings=new LinkedHashMap<String,Object>();long operations=0;
        for(Object raw:list(root.get("cases"))){var c=object(raw);var complexes=new ArrayList<CellPhoneDbStatistics.Complex>();for(Object item:list(c.get("complexes"))){var row=object(item);complexes.add(new CellPhoneDbStatistics.Complex(integer(row.get("id"),Long.MIN_VALUE,Long.MAX_VALUE),ids(row.get("proteins"))));}
            var prepared=new CellPhoneDbStatistics.Prepared(ids(c.get("proteins")),texts(c.get("cells")),texts(c.get("cell_types")),matrix(c.get("expression")),complexes,CellPhoneDbStatistics.Precision.valueOf(text(c.get("precision")).toUpperCase(Locale.ROOT)));var interactions=new ArrayList<CellPhoneDbStatistics.Interaction>();for(Object item:list(c.get("interactions"))){var row=object(item);interactions.add(new CellPhoneDbStatistics.Interaction(text(row.get("id")),integer(row.get("first"),Long.MIN_VALUE,Long.MAX_VALUE),integer(row.get("second"),Long.MIN_VALUE,Long.MAX_VALUE)));}
            var environments=new ArrayList<CellPhoneDbStatistics.Microenvironment>();for(Object item:list(c.get("microenvironments"))){var row=object(item);environments.add(new CellPhoneDbStatistics.Microenvironment(text(row.get("cell_type")),text(row.get("environment"))));}
            List<CellPhoneDbStatistics.Deg> degs=null;if(c.get("degs")!=null){degs=new ArrayList<>();for(Object item:list(c.get("degs"))){var row=object(item);degs.add(new CellPhoneDbStatistics.Deg(integer(row.get("protein"),Long.MIN_VALUE,Long.MAX_VALUE),text(row.get("cell_type"))));}}
            var permutations=new ArrayList<List<String>>();for(Object row:list(c.get("permutation_labels")))permutations.add(texts(row));var result=CellPhoneDbStatistics.analyze(prepared,interactions,environments,number(c.get("threshold")),text(c.get("separator")),permutations,c.get("pvalue_cutoff")==null?null:number(c.get("pvalue_cutoff")),degs,CellPhoneDbStatistics.Limits.defaults());
            var report=new LinkedHashMap<String,Object>();report.put("id",text(c.get("id")));report.put("cluster_features",result.clusters().features());report.put("cell_types",result.clusters().cellTypes());report.put("cluster_means",values(result.clusters().means()));report.put("cluster_percents",values(result.clusters().percents()));report.put("pairs",result.pairs().stream().map(p->List.of(p.first(),p.second())).toList());report.put("columns",result.columns());report.put("interaction_ids",result.interactions().stream().map(CellPhoneDbStatistics.Interaction::id).toList());report.put("means",values(result.means()));report.put("eligible",values(result.eligible()));report.put("non_statistical",significant(result.nonStatistical()));var shuffled=new ArrayList<Object>();for(double[][] row:result.permutedMeans())shuffled.add(values(row));report.put("permuted_means",shuffled);var packed=new ArrayList<Object>();for(byte[] row:result.packedGreater()){var next=new ArrayList<Integer>();for(byte value:row)next.add(Byte.toUnsignedInt(value));packed.add(next);}report.put("packed_greater",packed);report.put("pvalues",result.pvalues()==null?null:values(result.pvalues()));report.put("statistical",significant(result.statistical()));
            var flags=result.degs();report.put("degs",flags==null?null:Map.of("features",flags.features(),"cell_types",flags.cellTypes(),"flags",values(flags.flags()),"ignored_marks",flags.ignoredMarks().stream().map(m->Map.of("protein",m.protein(),"cell_type",m.cellType())).toList()));report.put("deg_relevant",values(result.degRelevant()));report.put("deg_significant",significant(result.degSignificant()));results.add(report);warnings.put(text(c.get("id")),result.warnings());operations+=result.operations();
        }
        var rejected=new ArrayList<String>();var good=new CellPhoneDbStatistics.Prepared(List.of(1L,2L),List.of("c1","c2"),List.of("A","B"),new double[][]{{1,2},{3,4}},List.of());var interactions=List.of(new CellPhoneDbStatistics.Interaction("I",1,2));var defaults=CellPhoneDbStatistics.Limits.defaults();
        reject("negative-expression",()->run(new CellPhoneDbStatistics.Prepared(good.proteins(),good.cells(),good.cellTypes(),new double[][]{{-1,2},{3,4}},List.of()),interactions,defaults),rejected);
        reject("nonfinite-expression",()->run(new CellPhoneDbStatistics.Prepared(good.proteins(),good.cells(),good.cellTypes(),new double[][]{{Double.NaN,2},{3,4}},List.of()),interactions,defaults),rejected);
        reject("silent-float32-input-rounding",()->run(new CellPhoneDbStatistics.Prepared(good.proteins(),good.cells(),good.cellTypes(),new double[][]{{.1,2},{3,4}},List.of(),CellPhoneDbStatistics.Precision.FLOAT32),interactions,defaults),rejected);
        reject("ragged-expression",()->run(new CellPhoneDbStatistics.Prepared(good.proteins(),good.cells(),good.cellTypes(),new double[][]{{1},{3,4}},List.of()),interactions,defaults),rejected);
        reject("duplicate-cell",()->run(new CellPhoneDbStatistics.Prepared(good.proteins(),List.of("x","x"),good.cellTypes(),good.expression(),List.of()),interactions,defaults),rejected);
        reject("duplicate-protein",()->run(new CellPhoneDbStatistics.Prepared(List.of(1L,1L),good.cells(),good.cellTypes(),good.expression(),List.of()),interactions,defaults),rejected);
        reject("unpaired-cell-label",()->new CellPhoneDbStatistics.Interaction("\ud800",1,2),rejected);
        reject("incomplete-complex",()->run(new CellPhoneDbStatistics.Prepared(good.proteins(),good.cells(),good.cellTypes(),good.expression(),List.of(new CellPhoneDbStatistics.Complex(3,List.of(9L)))),interactions,defaults),rejected);
        reject("absent-interaction-endpoint",()->run(good,List.of(new CellPhoneDbStatistics.Interaction("I",1,9)),defaults),rejected);
        reject("duplicate-interaction-id",()->run(good,List.of(interactions.get(0),interactions.get(0)),defaults),rejected);
        reject("threshold-outside-profile",()->CellPhoneDbStatistics.analyze(good,interactions,List.of(),1.1,"|",List.of(),null,null,defaults),rejected);
        reject("unknown-microenvironment-cell-type",()->CellPhoneDbStatistics.analyze(good,interactions,List.of(new CellPhoneDbStatistics.Microenvironment("outside","E")),.1,"|",List.of(),null,null,defaults),rejected);
        reject("incomplete-permutation",()->CellPhoneDbStatistics.analyze(good,interactions,List.of(),.1,"|",List.of(List.of("A")),.05,null,defaults),rejected);
        reject("permutation-multiset-changed",()->CellPhoneDbStatistics.analyze(good,interactions,List.of(),.1,"|",List.of(List.of("A","A")),.05,null,defaults),rejected);
        reject("original-empty-composition-DEG-failure",()->CellPhoneDbStatistics.analyze(good,interactions,List.of(),.1,"|",List.of(),null,List.of(new CellPhoneDbStatistics.Deg(1,"A")),defaults),rejected);
        reject("cell-capacity",()->run(good,interactions,new CellPhoneDbStatistics.Limits(1,10,10,10,10,10000)),rejected);
        reject("pair-capacity",()->run(good,interactions,new CellPhoneDbStatistics.Limits(10,10,1,10,10,10000)),rejected);
        reject("operation-capacity",()->run(good,interactions,new CellPhoneDbStatistics.Limits(10,10,10,10,10,1)),rejected);
        reject("retained-permutation-capacity-before-allocation",()->CellPhoneDbStatistics.analyze(good,interactions,List.of(),.1,"|",Collections.nCopies(100,good.cellTypes()),.05,null,new CellPhoneDbStatistics.Limits(10,10,10,10,200,100)),rejected);
        Thread.currentThread().interrupt();try{reject("thread-cancellation",()->run(good,interactions,defaults),rejected);}finally{Thread.interrupted();}
        double[][] raw={{1,2},{3,4}};var protectedInput=new CellPhoneDbStatistics.Prepared(good.proteins(),good.cells(),good.cellTypes(),raw,List.of());raw[0][0]=999;protectedInput.expression()[0][0]=888;require(protectedInput.expression()[0][0]==1,"Input alias changed prepared scientific values");var protectedResult=run(protectedInput,interactions,defaults);double first=protectedResult.means()[0][0];protectedResult.means()[0][0]=777;protectedResult.clusters().means()[0][0]=777;require(protectedResult.means()[0][0]==first&&protectedResult.clusters().means()[0][0]==1,"Output alias changed retained numerical values");
        require(Arrays.equals(original,NextflowFiles.bytes(input,67108864)),"Original cases changed");NextflowFiles.writeJson(out.resolve("results.json"),Map.of("cases",results));NextflowFiles.writeJson(out.resolve("WARNINGS.json"),warnings);NextflowFiles.writeJson(out.resolve("COMPLETED.json"),Map.of("status","PASS_NATIVE_CELLPHONEDB_PREPARED_KERNELS_ONLY","cases",results.size(),"expected_native_rejections",rejected,"defensive_copy_controls",true,"operations",operations,"implementation_credit",false,"whole_goal_complete",false));
    }
    private static CellPhoneDbStatistics.Result run(CellPhoneDbStatistics.Prepared input,List<CellPhoneDbStatistics.Interaction> interactions,CellPhoneDbStatistics.Limits limits){return CellPhoneDbStatistics.analyze(input,interactions,List.of(),.1,"|",List.of(),null,null,limits);}
    @FunctionalInterface private interface Check {Object run()throws Exception;}
    private static void reject(String name,Check action,List<String> rejected)throws Exception{boolean failed=false;try{action.run();}catch(IllegalArgumentException expected){failed=true;}require(failed,"Invalid native input admitted: "+name);rejected.add(name);}
}
